-- Fakt kartochkalarining ruscha matni — 12-partiya:
-- Narshaxiy, G'iyosiddin Jamshid Koshiy, Ali Qushchi.

-- ===== Narshaxiy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'От названия какого селения взята нисба Абу Бакра Наршахи?', fact_ru = 'Я родился в 899 году в селении Наршах близ Бухары. Моя нисба «Наршахи» взята от названия этого селения.' WHERE id = 463;
UPDATE fact_cards SET topic_ru = 'Моё полное имя', question_ru = 'В каком труде сохранилось полное имя Наршахи?', fact_ru = 'Моё полное имя — Абу Бакр Мухаммад ибн Джафар ибн Закария ибн Хаттаб ибн Шарик — сохранилось в труде Самани «Китаб ул-ансаб». Там же отмечено, что я родился в 899 году и умер в 959 году.' WHERE id = 464;
UPDATE fact_cards SET topic_ru = 'Моя книга «История Бухары»', question_ru = 'Когда и на каком языке Наршахи написал книгу «История Бухары»?', fact_ru = 'В 943–944 годах я написал на арабском языке книгу «История Бухары». Это древнейший исторический труд Средней Азии, написанный местным автором и дошедший до нас полностью.' WHERE id = 465;
UPDATE fact_cards SET topic_ru = 'Кому посвящена моя книга', question_ru = 'Какому правителю Наршахи посвятил свою книгу?', fact_ru = 'Свою книгу я посвятил саманидскому правителю эмиру Нуху ибн Насру.' WHERE id = 466;
UPDATE fact_cards SET topic_ru = 'Содержание моей книги', question_ru = 'О чём повествует труд Наршахи «История Бухары»?', fact_ru = 'В своём труде я рассказал о городе Бухаре и её селениях, каналах, правителях, судьях и о жизни народа. В нём освещены также время арабского завоевания и история Саманидов.' WHERE id = 467;
UPDATE fact_cards SET topic_ru = 'Что я написал о Муканне', question_ru = 'О каком восстании Наршахи подробно написал в своей книге?', fact_ru = 'В книге я подробно рассказал и о восстании «людей в белом» под началом Муканны, в том числе описал битву 776 года у моего родного селения Наршах.' WHERE id = 468;
UPDATE fact_cards SET topic_ru = 'Перевод на персидский', question_ru = 'Кто перевёл книгу Наршахи на персидский язык?', fact_ru = 'Я скончался в 959 году, но книга моя продолжала жить. Её арабский подлинник до нас не дошёл. После моей смерти, в 1128 году, Абу Наср Ахмад аль-Кубави, родом из города Кува, перевёл её на персидский и сократил.' WHERE id = 469;
UPDATE fact_cards SET topic_ru = 'Позднейшая редакция', question_ru = 'Кто вновь сократил и изложил персидский перевод Наршахи?', fact_ru = 'Я скончался в 959 году. Много позже, в 1178–1179 годах, Мухаммад ибн Зуфар ещё раз сократил и изложил персидский перевод. Так моя книга веками переписывалась и переходила из поколения в поколение.' WHERE id = 470;
UPDATE fact_cards SET topic_ru = 'Названия моей книги', question_ru = 'Под какими ещё названиями была известна книга Наршахи?', fact_ru = 'Моя книга была известна под разными названиями: «Тарихи Наршахи», «Тарихи Бухоро», «Тахкик ул-вилоят» и «Ахбори Бухоро». В нынешней науке твёрдо закрепилось название «История Бухары».' WHERE id = 471;
UPDATE fact_cards SET topic_ru = 'Мировое признание', question_ru = 'В каких городах была издана книга Наршахи?', fact_ru = 'Я скончался в 959 году, но книга моя после меня отправилась в путешествие по свету. Она была издана в 1892 году в Париже, в 1897 году в Ташкенте на русском языке, в 1954 году в Кембридже на английском, а в 1966 году — на узбекском в переводе А. Расулева.' WHERE id = 472;
UPDATE fact_cards SET topic_ru = 'Время моей жизни', question_ru = 'В правление какой династии жил и творил Абу Бакр Наршахи?', fact_ru = 'Я жил в пору правления государства Саманидов. Бухара тогда была столицей и стала крупным центром науки и культуры.' WHERE id = 1737;
UPDATE fact_cards SET topic_ru = 'Почему я писал по-арабски', question_ru = 'Почему Абу Бакр Наршахи написал «Историю Бухары» на арабском языке?', fact_ru = 'Свою книгу я написал на арабском языке, потому что в то время арабский считался языком науки на всём Востоке.' WHERE id = 1738;
UPDATE fact_cards SET topic_ru = 'Судьба подлинника', question_ru = 'В каком виде дошёл до нас труд Абу Бакра Наршахи «История Бухары»?', fact_ru = 'Арабский подлинник моей книги до нас не дошёл. Мой труд сохранился благодаря персидскому переводу и сокращённым редакциям, сделанным в последующие века.' WHERE id = 1739;
UPDATE fact_cards SET topic_ru = 'Древние названия Бухары', question_ru = 'Какое древнее название города Бухары привёл Абу Бакр Наршахи в своей книге?', fact_ru = 'В своей книге я написал, что в древности город Бухара назывался несколькими именами. Одним из них было Нумиджкат.' WHERE id = 1740;
UPDATE fact_cards SET topic_ru = 'Предание о Сиявуше', question_ru = 'Какой легендарный царевич, согласно преданию из книги Абу Бакра Наршахи, построил бухарский Арк?', fact_ru = 'В книге я привёл и древние предания, связанные с бухарским Арком. По преданиям, Арк будто бы построил легендарный царевич Сиявуш.' WHERE id = 1741;
UPDATE fact_cards SET topic_ru = 'Описание окрестных селений', question_ru = 'Какой древний городок в окрестностях Бухары описал Абу Бакр Наршахи в «Истории Бухары»?', fact_ru = 'В книге я описал не только сам город Бухару, но и множество окрестных селений и городков. Среди них и древний город Пайкенд.' WHERE id = 1742;
UPDATE fact_cards SET topic_ru = 'Издание на узбекском', question_ru = 'Когда труд Абу Бакра Наршахи «История Бухары» был издан на узбекском языке?', fact_ru = 'Я скончался в 959 году. Спустя много веков после моей смерти, в 1966 году, моя книга была издана на узбекском языке в переводе А. Расулева. Теперь и ты можешь прочесть её на своём родном языке.' WHERE id = 1743;

-- ===== G'iyosiddin Jamshid Koshiy =====
UPDATE fact_cards SET topic_ru = 'Мой приезд в Самарканд', question_ru = 'Когда Улугбек призвал Гиясиддина Джамшида Каши в Самарканд?', fact_ru = 'В 1417 году Улугбек призвал меня в Самарканд.' WHERE id = 340;
UPDATE fact_cards SET topic_ru = 'Проект обсерватории', question_ru = 'Какую роль сыграл Гиясиддин Джамшид Каши в строительстве Самаркандской обсерватории?', fact_ru = 'Я был одним из зачинателей проекта Самаркандской обсерватории.' WHERE id = 341;
UPDATE fact_cards SET topic_ru = 'Круг учёных', question_ru = 'С кем работал Гиясиддин Джамшид Каши в кругу Улугбека?', fact_ru = 'В кругу Улугбека я работал вместе с Казизаде Руми и юным Али Кушчи.' WHERE id = 342;
UPDATE fact_cards SET topic_ru = '«Мифтах ул-хисоб»', question_ru = 'Когда Каши завершил труд «Мифтах ул-хисоб»?', fact_ru = 'Свой труд «Мифтах ул-хисоб» («Ключ арифметики») я завершил в 1427 году.' WHERE id = 343;
UPDATE fact_cards SET topic_ru = 'Кем я был наставником', question_ru = 'Кем был Гиясиддин Джамшид Каши для Улугбека?', fact_ru = 'Я был одним из знаменитых наставников Улугбека — он глубоко меня почитал.' WHERE id = 344;
UPDATE fact_cards SET topic_ru = 'Моя смерть', question_ru = 'Когда умер Гиясиддин Джамшид Каши?', fact_ru = 'Я скончался в 1430 году — это стало большой потерей для школы, составлявшей звёздные таблицы.' WHERE id = 345;
UPDATE fact_cards SET topic_ru = 'Моё наследие', question_ru = 'Развитию какой науки послужили труды Каши?', fact_ru = 'Мои работы по науке счисления послужили развитию математики Востока.' WHERE id = 346;
UPDATE fact_cards SET topic_ru = 'Город, где я родился', question_ru = 'В каком городе родился Гиясиддин Джамшид Каши?', fact_ru = 'Я родился в городе Кашан. И прозвание моё «Каши» произошло от названия этого города.' WHERE id = 1599;
UPDATE fact_cards SET topic_ru = 'Мой труд «Зидж-и Хакани»', question_ru = 'Какую книгу астрономических таблиц написал Гиясиддин Каши?', fact_ru = 'До приезда в Самарканд я написал книгу астрономических таблиц под названием «Зидж-и Хакани».' WHERE id = 1600;
UPDATE fact_cards SET topic_ru = '«Суллам ус-само»', question_ru = 'О чём труд Гиясиддина Каши «Суллам ус-само»?', fact_ru = 'В труде «Суллам ус-само», то есть «Лестница небес», я написал об удалённости небесных тел от Земли и об их величине.' WHERE id = 1601;
UPDATE fact_cards SET topic_ru = 'Как я вычислил число пи', question_ru = 'С какой точностью Гиясиддин Каши вычислил число пи?', fact_ru = 'В своём трактате об окружности я вычислил число пи с точностью до шестнадцати знаков. Почти два века никто не смог превзойти этот результат.' WHERE id = 1602;
UPDATE fact_cards SET topic_ru = 'Десятичные дроби', question_ru = 'Каким открытием в математике знаменит Гиясиддин Каши?', fact_ru = 'Я в совершенстве разработал теорию десятичных дробей и широко применял их в вычислениях. История десятичных дробей, которые ты изучаешь в школе, восходит к моим трудам.' WHERE id = 1603;
UPDATE fact_cards SET topic_ru = 'Синус одного градуса', question_ru = 'Какую сложную задачу тригонометрии решил Гиясиддин Каши?', fact_ru = 'Я нашёл способ вычислять синус дуги в один градус с очень высокой точностью. Для астрономии того времени это была крайне важная задача.' WHERE id = 1604;
UPDATE fact_cards SET topic_ru = 'Глава обсерватории', question_ru = 'В какой должности работал Гиясиддин Каши в Самаркандской обсерватории?', fact_ru = 'Улугбек доверил мне ведение дел в Самаркандской обсерватории — я был первым её главой.' WHERE id = 1605;
UPDATE fact_cards SET topic_ru = 'Мои письма к отцу', question_ru = 'Почему письма Гиясиддина Каши к отцу считаются ценными?', fact_ru = 'Из Самарканда я писал письма отцу в Кашан. В них я подробно описал научную жизнь Улугбека и самаркандских учёных. Эти письма дошли до нас.' WHERE id = 1606;
UPDATE fact_cards SET topic_ru = 'Прибор, который я изобрёл', question_ru = 'Какой прибор изобрёл Гиясиддин Каши?', fact_ru = 'Я изобрёл особый прибор, вычисляющий положение планет на небе, и подробно описал его в своём труде.' WHERE id = 1607;
UPDATE fact_cards SET topic_ru = 'Отзыв Улугбека', question_ru = 'Как Улугбек отозвался о Гиясиддине Каши в своём труде «Зидж»?', fact_ru = 'Улугбек с почтением упомянул меня в предисловии к своему знаменитому труду «Зидж» и высоко оценил мои познания.' WHERE id = 1608;

-- ===== Ali Qushchi =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда родился Али Кушчи и где он вырос?', fact_ru = 'Я родился в 1403 году, вырос и возмужал в Самарканде.' WHERE id = 331;
UPDATE fact_cards SET topic_ru = 'Моё прозвище', question_ru = 'С чем связано прозвище Али Кушчи?', fact_ru = 'Моё прозвище «Кушчи» связано с птицами — так меня назвали из-за службы, связанной с соколиной охотой.' WHERE id = 332;
UPDATE fact_cards SET topic_ru = 'Мои наставники', question_ru = 'С какими учёными работал Али Кушчи в кругу Улугбека?', fact_ru = 'Улугбек считал меня своим учеником и молодым сподвижником; в его кругу учёных я работал вместе с Казизаде Руми и Гиясиддином Джамшидом Каши.' WHERE id = 333;
UPDATE fact_cards SET topic_ru = 'Моя первая лекция', question_ru = 'Когда Али Кушчи прочёл первую лекцию в медресе Улугбека?', fact_ru = 'В 1420 году я впервые прочёл лекцию студентам в медресе Улугбека.' WHERE id = 334;
UPDATE fact_cards SET topic_ru = 'Моя поездка в Китай', question_ru = 'Зачем Улугбек послал Али Кушчи в Китай?', fact_ru = 'Улугбек послал меня в Китай, чтобы разыскать китайские пособия и календари по астрономии.' WHERE id = 335;
UPDATE fact_cards SET topic_ru = 'Мой вклад в «Зидж»', question_ru = 'Каков был вклад Али Кушчи в завершение «Зидж-и джадид-и Гурагани»?', fact_ru = 'В завершении «Зидж-и джадид-и Гурагани» моя заслуга была велика — Улугбек особо отметил это в предисловии к труду.' WHERE id = 336;
UPDATE fact_cards SET topic_ru = 'Моё звание', question_ru = 'Каким званием называли Али Кушчи?', fact_ru = 'Меня называли «Птолемеем своего времени».' WHERE id = 337;
UPDATE fact_cards SET topic_ru = 'Мои труды', question_ru = 'На каких языках создавал научные труды Али Кушчи?', fact_ru = 'Научные труды я создавал на арабском и персидском языках.' WHERE id = 338;
UPDATE fact_cards SET topic_ru = 'Моё наследие', question_ru = 'Кем остался в истории Али Кушчи?', fact_ru = 'Я остался в истории как продолжатель и посланник научной школы Улугбека.' WHERE id = 339;
UPDATE fact_cards SET topic_ru = 'Мои наблюдения в обсерватории', question_ru = 'В какой обсерватории Али Кушчи наблюдал звёзды?', fact_ru = 'Я наблюдал звёзды в Самаркандской обсерватории Улугбека. В наблюдениях я был одним из ближайших помощников моего наставника Улугбека.' WHERE id = 1505;
UPDATE fact_cards SET topic_ru = '«Фарзанди арджуманд»', question_ru = 'Как называл Али Кушчи Мирзо Улугбек?', fact_ru = 'Мой наставник Мирзо Улугбек весьма ценил меня и называл «фарзанди арджуманд», то есть дорогим моим сыном.' WHERE id = 1506;
UPDATE fact_cards SET topic_ru = 'Мой отъезд из Самарканда', question_ru = 'По какой причине Али Кушчи покинул Самарканд?', fact_ru = 'После кончины моего наставника Улугбека я отправился из Самарканда в путь с намерением совершить хадж и некоторое время жил в городах Ирана.' WHERE id = 1507;
UPDATE fact_cards SET topic_ru = 'Как я стал послом в Тебризе', question_ru = 'Кто отправил Али Кушчи послом в Стамбул?', fact_ru = 'Правитель Тебриза Узун-Хасан принял меня с почётом и отправил послом в Стамбул — к султану Мехмеду Фатиху.' WHERE id = 1508;
UPDATE fact_cards SET topic_ru = 'В медресе Айя-Софии', question_ru = 'В каком медресе преподавал Али Кушчи в Стамбуле?', fact_ru = 'В Стамбуле я преподавал в медресе Айя-Софии. Послушать мои уроки собиралось великое множество студентов.' WHERE id = 1509;
UPDATE fact_cards SET topic_ru = 'Труды, написанные мной в Стамбуле', question_ru = 'Какие труды написал Али Кушчи в Стамбуле?', fact_ru = 'В Стамбуле я написал трактат по математике «Мухаммадия» и трактат по астрономии «Фатхия» и посвятил их султану Мехмеду Фатиху.' WHERE id = 1510;
UPDATE fact_cards SET topic_ru = 'Моё последнее пристанище', question_ru = 'В каком городе Али Кушчи жил в конце жизни?', fact_ru = 'Последние годы моей жизни прошли в Стамбуле. В 1474 году я скончался там и был погребён на кладбище Эйюп.' WHERE id = 1511;
